const fs = require('fs');

function mul(a, b, mod) {
    const m = a.length;
    const p = a[0].length;
    const n = b[0].length;
    const c = Array.from({ length: m }, () => Array(n).fill(0n));
    for (let i = 0; i < m; i++) {
        for (let k = 0; k < p; k++) {
            const aik = a[i][k];
            if (aik === 0n) continue;
            for (let j = 0; j < n; j++) {
                c[i][j] = (c[i][j] + aik * b[k][j]) % mod;
            }
        }
    }
    return c;
}

function q_pow(base, exp, mod) {
    const size = base.length;
    let ans = Array.from({ length: size }, (_, i) =>
        Array.from({ length: size }, (_, j) => (i === j ? 1n : 0n))
    );
    let b = base.map(row => [...row]);
    let n = exp;
    while (n > 0n) {
        if ((n & 1n) === 1n) {
            ans = mul(ans, b, mod);
        }
        b = mul(b, b, mod);
        n >>= 1n;
    }
    return ans;
}

function solve() {
    const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
    if (data.length === 0) return;

    const out = [];
    for (let i = 0; i < data.length; i += 6) {
        const n = BigInt(data[i]);
        const sx = BigInt(data[i + 1]);
        const sy = BigInt(data[i + 2]);
        const dx = BigInt(data[i + 3]);
        const dy = BigInt(data[i + 4]);
        const t = BigInt(data[i + 5]);

        const a = [
            [2n, 1n, 1n, 0n, 1n, 2n],
            [1n, 2n, 0n, 1n, 1n, 2n],
            [1n, 1n, 1n, 0n, 1n, 2n],
            [1n, 1n, 0n, 1n, 1n, 2n],
            [0n, 0n, 0n, 0n, 1n, 1n],
            [0n, 0n, 0n, 0n, 0n, 1n]
        ];

        const a_pow = q_pow(a, t, n);

        const b = [
            [(sx - 1n + n) % n],
            [(sy - 1n + n) % n],
            [(dx % n + n) % n],
            [(dy % n + n) % n],
            [0n],
            [1n]
        ];

        const res = mul(a_pow, b, n);
        const final_x = (res[0][0] + 1n).toString();
        const final_y = (res[1][0] + 1n).toString();
        out.push(`${final_x} ${final_y}`);
    }
    console.log(out.join('\n'));
}

solve();

